let instance: Gtk4SessionLock.Instance | null = null;
let locked = false;
const subscribers = new Set<LockSubscriber>();

// Compositor `::failed` recovery. Morning idle-timeout-driven locks race
// with monitor reinitialization (DPMS / suspend wake) — short backoffs
// let those transitions settle before the screen would otherwise be left
// silently unlocked.
const RETRY_BACKOFF_MS = [250, 1000, 4000] as const;
const MAX_LOCK_ATTEMPTS = 1 + RETRY_BACKOFF_MS.length;
let attemptCount = 0;
let attemptStartMs = 0;
const retryTimer = createManagedTimer();

input.old_string:
instance.connect("failed", () => {
  logError("::failed signal fired — lock not acquired");
  instance = null;
});

input.new_string:
instance.connect("failed", () => {
  if (attemptCount < MAX_LOCK_ATTEMPTS) {
    const delay = RETRY_BACKOFF_MS[attemptCount - 1] ?? 4000;
    retryTimer.schedule(delay, () => attemptLock());
    return;
  }
  logError(`::failed after ${attemptCount} attempts in ${Date.now() - attemptStartMs}ms`);
  instance = null;
});
